# Bài đọc (Reading) và đề viết (Writing) theo cấp độ.
# Chạy: python3 data-src/reading.py  → ghi data/skills.json
import json, pathlib

R = []  # bài đọc
def passage(level, title, title_vi, text, vi, questions):
    R.append({"id": f"{level.lower()}-r{sum(1 for p in R if p['level']==level)+1}", "level": level,
              "title": title, "titleVi": title_vi, "text": text.strip(), "vi": vi.strip(),
              "questions": [{"q": q, "options": o, "answer": a, "explain": ex} for q, o, a, ex in questions]})

